using NSubstitute;
using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly IPaymentProcessor _processor;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _processor = Substitute.For<IPaymentProcessor>();
        _gateway = new PaymentGateway(_processor);
    }

    // --- Construction ---

    [TestMethod]
    public void Constructor_NullProcessor_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
        Assert.AreEqual("processor", ex.ParamName);
    }

    // --- ChargeAsync: validation ---

    [TestMethod]
    [DataRow(null, DisplayName = "null token")]
    [DataRow("", DisplayName = "empty token")]
    [DataRow("   ", DisplayName = "whitespace token")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? token)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token!, 10m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "zero amount")]
    [DataRow(-1, DisplayName = "negative amount")]
    [DataRow(-0.01, DisplayName = "slightly negative")]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRangeException(double rawAmount)
    {
        var amount = (decimal)rawAmount;

        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaximum_ThrowsArgumentOutOfRangeException()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", 1_000_000m));
        Assert.AreEqual("amount", ex.ParamName);
    }

    // --- ChargeAsync: happy path ---

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessResult()
    {
        var expected = new ChargeResult("ch_123", true);
        _processor.ProcessChargeAsync("tok_abc", 49.99m, Arg.Any<CancellationToken>())
            .Returns(expected);

        var result = await _gateway.ChargeAsync("tok_abc", 49.99m);

        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProcessorReturnsFailed_PropagatesResult()
    {
        _processor.ProcessChargeAsync(Arg.Any<string>(), Arg.Any<decimal>(), Arg.Any<CancellationToken>())
            .Returns(new ChargeResult("ch_fail", false));

        var result = await _gateway.ChargeAsync("tok_abc", 10m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "minimum")]
    [DataRow(999999.99, DisplayName = "maximum")]
    [DataRow(500.00, DisplayName = "typical")]
    public async Task ChargeAsync_BoundaryAmounts_DelegatesToProcessor(double rawAmount)
    {
        var amount = (decimal)rawAmount;
        _processor.ProcessChargeAsync(Arg.Any<string>(), amount, Arg.Any<CancellationToken>())
            .Returns(new ChargeResult("ch_ok", true));

        var result = await _gateway.ChargeAsync("tok_valid", amount);

        Assert.IsTrue(result.Success);
        await _processor.Received(1).ProcessChargeAsync("tok_valid", amount, Arg.Any<CancellationToken>());
    }

    [TestMethod]
    public async Task ChargeAsync_ForwardsCancellationToken()
    {
        using var cts = new CancellationTokenSource();
        _processor.ProcessChargeAsync(Arg.Any<string>(), Arg.Any<decimal>(), cts.Token)
            .Returns(new ChargeResult("ch_ok", true));

        await _gateway.ChargeAsync("tok_valid", 10m, cts.Token);

        await _processor.Received(1).ProcessChargeAsync("tok_valid", 10m, cts.Token);
    }

    // --- RefundAsync: validation ---

    [TestMethod]
    [DataRow(null, DisplayName = "null chargeId")]
    [DataRow("", DisplayName = "empty chargeId")]
    [DataRow("  ", DisplayName = "whitespace chargeId")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    // --- RefundAsync: happy path ---

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsRefundResult()
    {
        var expected = new RefundResult("re_456", true);
        _processor.ProcessRefundAsync("ch_123", Arg.Any<CancellationToken>())
            .Returns(expected);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.AreEqual("re_456", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ProcessorReturnsFailed_PropagatesResult()
    {
        _processor.ProcessRefundAsync(Arg.Any<string>(), Arg.Any<CancellationToken>())
            .Returns(new RefundResult("re_fail", false));

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ForwardsCancellationToken()
    {
        using var cts = new CancellationTokenSource();
        _processor.ProcessRefundAsync(Arg.Any<string>(), cts.Token)
            .Returns(new RefundResult("re_ok", true));

        await _gateway.RefundAsync("ch_123", cts.Token);

        await _processor.Received(1).ProcessRefundAsync("ch_123", cts.Token);
    }

    // --- ProcessWebhook ---

    [TestMethod]
    [DataRow("charge.succeeded", "Charge confirmed")]
    [DataRow("charge.failed", "Charge failed")]
    [DataRow("refund.completed", "Refund confirmed")]
    public void ProcessWebhook_KnownEvent_ReturnsProcessed(string eventType, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.AreEqual(WebhookStatus.Processed, result.Status);
        Assert.AreEqual(expectedMessage, result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_UnknownEvent_ReturnsIgnored()
    {
        var result = _gateway.ProcessWebhook("invoice.created", "{\"id\":\"evt_2\"}");

        Assert.AreEqual(WebhookStatus.Ignored, result.Status);
        Assert.Contains("Unknown event", result.Message);
    }

    [TestMethod]
    [DataRow(null, "{}", DisplayName = "null eventType")]
